import hashlib
import importlib.metadata
import sys

import pytest

from ia_driver.env import collect_environment, norm, parse_lock

LOCK = """\
# This file is autogenerated by pip-compile
#
--index-url https://example.invalid/simple
pydantic==2.11.9 \\
    --hash=sha256:aa \\
    --hash=sha256:bb
    # via cognous
Typing_Extensions==4.12.2 ; python_version >= "3.8" \\
    --hash=sha256:cc
pytest==8.3.5 \\
    --hash=sha256:dd  # a comment
"""
DISTS = [("pydantic", "2.11.9"), ("typing-extensions", "4.12.2"), ("pytest", "8.3.5")]
SP = [sys.path[0]] if sys.path else []


def run(tmp_path, lock=LOCK, dists=DISTS, **kw):
    p = tmp_path / "lock.txt"
    p.write_text(lock)
    kw.setdefault("expected_sys_path", list(sys.path))
    return collect_environment(str(p), distributions=dists, **kw), p


def test_parse_lock_ignores_comments_and_continuations():
    pins, hashes, errors = parse_lock(LOCK)
    assert pins == {"pydantic": "2.11.9", "typing-extensions": "4.12.2", "pytest": "8.3.5"}
    assert hashes == {"pydantic": 2, "typing-extensions": 1, "pytest": 1} and errors == []
    assert norm("Typing_Extensions") == "typing-extensions"


def test_matching_environment(tmp_path):
    r, p = run(tmp_path)
    assert r["missing_from_env"] == [] and r["extra_in_env"] == [] and r["mismatched_versions"] == {}
    assert r["errors"] == []
    assert r["lock_sha256"] == hashlib.sha256(p.read_bytes()).hexdigest()
    assert r["python"]["version"].count(".") == 2 and r["python"]["executable"] == sys.executable
    assert r["distributions"]["pydantic"] == "2.11.9"
    # ok additionally requires isolated + dont_write_bytecode: it must track the real flags
    assert r["ok"] == bool(sys.flags.isolated and sys.flags.dont_write_bytecode)
    assert r["sys_flags_ok"] == r["ok"]


def test_missing_extra_mismatch(tmp_path):
    r, _ = run(tmp_path, dists=[("pydantic", "2.11.8"), ("pytest", "8.3.5"), ("evil", "1.0")])
    assert r["missing_from_env"] == ["typing-extensions"]
    assert r["extra_in_env"] == ["evil"]
    assert r["mismatched_versions"] == {"pydantic": {"lock": "2.11.9", "installed": "2.11.8"}}
    assert r["ok"] is False


def test_allow_list_for_components_and_tooling(tmp_path):
    comps = [("agent-control-plane", "0.1"), ("pip", "24.0"), ("setuptools", "70"), ("wheel", "0.4")]
    r, _ = run(tmp_path, dists=DISTS + comps)
    assert r["extra_in_env"] == ["agent-control-plane"]  # components not allowed unless named
    r, _ = run(tmp_path, dists=DISTS + comps, allow_extra=["Agent_Control_Plane"])
    assert r["extra_in_env"] == []
    r, _ = run(tmp_path, dists=DISTS + comps, allow_extra=["agent-control-plane"], allow_tooling=())
    assert r["extra_in_env"] == ["pip", "setuptools", "wheel"]


def test_duplicate_distribution_is_error(tmp_path):
    r, _ = run(tmp_path, dists=DISTS + [("pydantic", "2.11.9")])
    assert any("duplicate distributions" in e for e in r["errors"]) and r["ok"] is False


def test_lock_problems_are_errors(tmp_path):
    r, _ = run(tmp_path, lock="pydantic==1.0\n")
    assert any("without --hash" in e for e in r["errors"]) and r["ok"] is False
    r, _ = run(tmp_path, lock="# nothing\n")
    assert any("no pins" in e for e in r["errors"]) and r["ok"] is False
    r, _ = run(tmp_path, lock="pydantic>=1.0 --hash=sha256:aa\n")
    assert any("unparseable" in e for e in r["errors"])
    r = collect_environment(str(tmp_path / "absent.txt"), distributions=DISTS, expected_sys_path=sys.path)
    assert r["lock_sha256"] is None and r["ok"] is False and r["errors"]


def test_sys_path_must_be_expected(tmp_path):
    r, _ = run(tmp_path, expected_sys_path=["/definitely/not/on/path"])
    assert r["unexpected_sys_path"] == [p for p in sys.path] and r["ok"] is False
    r, _ = run(tmp_path, expected_sys_path=list(sys.path)[:-1] if len(sys.path) > 1 else [])
    assert r["unexpected_sys_path"] == ([sys.path[-1]] if len(sys.path) > 1 else list(sys.path))
    r, _ = run(tmp_path, expected_sys_path=None)
    assert r["unexpected_sys_path"] is None and r["ok"] is False  # unchecked path is never ok


def test_real_interpreter_distributions(tmp_path):
    seen = {}
    for d in importlib.metadata.distributions():  # same order and last-wins rule as the collector
        if d.metadata["Name"]:
            seen[norm(d.metadata["Name"])] = d.version
    real = sorted(seen.items())
    lock = "".join(f"{n}=={v} \\\n    --hash=sha256:00\n" for n, v in real)
    r, _ = run(tmp_path, lock=lock, dists=None)
    assert r["missing_from_env"] == [] and r["extra_in_env"] == [] and r["mismatched_versions"] == {}
    assert "pytest" in r["distributions"]
    bumped = lock.replace("pytest==", "pytest==99.", 1)
    r, _ = run(tmp_path, lock=bumped, dists=None)
    assert "pytest" in r["mismatched_versions"]
